@@ -0,0 +1,100 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * What the customer list is narrowed down to. Understood by
+ * {@link CustomerRepository}, which applies it to both the page query and the
+ * count query, so a filtered grid stays as lazily loaded as an unfiltered one.
+ *
+ * @param name     free text; split on whitespace into terms, each of which must
+ *                 occur in the first or the last name. Case and accents are
+ *                 ignored, in both directions: {@code makinen} and
+ *                 {@code mäkinen} both match {@code Mäkinen}. Blank matches
+ *                 every customer.
+ * @param statuses the statuses to show; empty shows every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        // Leading, trailing and repeated whitespace means nothing to the terms,
+        // so two filters that differ only in it are the same filter.
+        name = (name == null) ? "" : WHITESPACE.matcher(name.strip()).replaceAll(" ");
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** A filter on the name only. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** A filter on the statuses only. */
+    public static CustomerFilter byStatus(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+
+    /** Whether this filter lets every customer through. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /**
+     * The name filter split into the terms a customer has to contain, folded to
+     * lower case without accents. Empty when the name filter is blank.
+     */
+    public List<String> nameTerms() {
+        return name.isEmpty() ? List.of() : List.of(WHITESPACE.split(fold(name)));
+    }
+
+    /**
+     * This filter as a predicate. The terms are folded once, up front, rather
+     * than once per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        return customer -> matchesStatus(customer, statuses) && matchesName(customer, terms);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        // Every term has to be found, but each may sit in either name.
+        return terms.stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /**
+     * Lower-cases {@code text} and strips its accents, so that {@code makinen},
+     * {@code MAKINEN} and {@code mäkinen} all fold to the same thing as
+     * {@code Mäkinen}.
+     */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
