+    }
+
+    /**
+     * Puts the filter in the address bar. This replaces the current history
+     * entry rather than adding one, so typing a name does not leave a trail of
+     * entries to press Back through.
+     */
+    private void writeFilterToUrl() {
+        getUI().ifPresent(ui -> ui.getPage().getHistory()
+                .replaceState(null, new FilterLocation(queryString())));
+    }
+
+    private String queryString() {
+        List<String> parameters = new ArrayList<>();
+        if (!filter.name().isEmpty()) {
+            parameters.add(NAME_PARAM + "=" + encode(filter.name()));
+        }
+        if (!filter.statuses().isEmpty()) {
+            // The statuses are held in declaration order, which is the order
+            // they are listed in.
+            parameters.add(STATUS_PARAM + "=" + filter.statuses().stream()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(",")));
+        }
+        return String.join("&", parameters);
+    }
+
+    private static String encode(String value) {
+        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
+    }
+
+    /**
+     * A location whose query string is written exactly as built above.
+     *
+     * <p>{@link QueryParameters} percent-encodes the commas between statuses,
+     * which would leave {@code ?status=ACTIVE%2CCLOSED} in the address bar. The
+     * URL is part of what this view offers its users, so it is spelled out here.
+     */
+    private static final class FilterLocation extends Location {
+
+        private final String pathWithQueryParameters;
+
+        private FilterLocation(String queryString) {
+            super("", QueryParameters.fromString(queryString));
+            this.pathWithQueryParameters = queryString.isEmpty() ? "" : "?" + queryString;
+        }
+
+        @Override
+        public String getPathWithQueryParameters() {
+            return pathWithQueryParameters;
+        }
+    }
 }
