+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** What the filter considers a match. */
+class CustomerFilterTest {
+
+    private static final Customer ADA =
+            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JARNO =
+            new Customer(2, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE =
+            new Customer(3, "Joséphine", "Aaltonen", "jos@example.com", "Portugal", CustomerStatus.CLOSED);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+
+    @Test
+    void emptyFilterMatchesEverything() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(matches(CustomerFilter.EMPTY, ADA));
+        assertTrue(matches(CustomerFilter.byName("   "), JARNO));
+    }
+
+    @Test
+    void everyTermHasToOccurInEitherName() {
+        assertTrue(matches(CustomerFilter.byName("ada aal"), ADA));
+        assertTrue(matches(CustomerFilter.byName("aal ada"), ADA));
+        assertTrue(matches(CustomerFilter.byName("  ada   aal  "), ADA));
+        assertFalse(matches(CustomerFilter.byName("ada virtanen"), ADA));
+    }
+
+    @Test
+    void caseAndAccentsAreIgnoredInBothDirections() {
+        for (String term : List.of("makinen", "MAKINEN", "mäkinen", "MÄKINEN", "Mäkinen")) {
+            assertTrue(matches(CustomerFilter.byName(term), JARNO), term + " should match Mäkinen");
+        }
+        assertTrue(matches(CustomerFilter.byName("josephine"), JOSEPHINE));
+        assertTrue(matches(CustomerFilter.byName("joséphine"), JOSEPHINE));
+    }
+
+    @Test
+    void noStatusSelectedMeansEveryStatus() {
+        assertTrue(matches(CustomerFilter.byStatus(), ADA));
+        assertTrue(matches(CustomerFilter.byStatus(CustomerStatus.ACTIVE), ADA));
+        assertFalse(matches(CustomerFilter.byStatus(CustomerStatus.CLOSED), ADA));
+        assertTrue(matches(CustomerFilter.byStatus(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), JOSEPHINE));
+    }
+
+    @Test
+    void bothFiltersHaveToBeSatisfied() {
+        CustomerFilter filter = new CustomerFilter("aaltonen", Set.of(CustomerStatus.CLOSED));
+        assertTrue(matches(filter, JOSEPHINE));
+        assertFalse(matches(filter, ADA), "Ada Aaltonen is ACTIVE, not CLOSED");
+        assertFalse(matches(filter, JARNO), "Jarno Mäkinen is not an Aaltonen");
+    }
+
+    @Test
+    void statusesAreHeldInDeclarationOrder() {
+        CustomerFilter filter = CustomerFilter.byStatus(CustomerStatus.CLOSED, CustomerStatus.ACTIVE);
+        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), List.copyOf(filter.statuses()));
+    }
+
+    @Test
+    void termsAreFoldedOnce() {
+        assertEquals(List.of("ada", "aal"), CustomerFilter.byName("  Ada   AAL ").nameTerms());
+        assertEquals(List.of("makinen"), CustomerFilter.byName("Mäkinen").nameTerms());
+        assertEquals(List.of(), CustomerFilter.byName(" ").nameTerms());
+    }
+}
