+        assertThat(summary()).hasText("Showing 10 of 500");
+        assertThat(nameFilter()).hasValue("vir");
+        assertEquals(2, statusFilter().getSelectedItemCount());
+        assertEquals(10, grid().getTotalRowCount());
+    }
+
+    /** Typing is not a query per keystroke, and never a query for every row. */
+    @Test
+    void typingANameCostsOneOrTwoQueries() {
+        assertThat(summary()).hasText("Showing 500 of 500");
+        queryLog.clear();
+
+        nameFilter().pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(60));
+        assertThat(summary()).hasText("Showing 15 of 500");
+
+        int queries = queryLog.pageQueries().size() + queryLog.countQueries().size();
+        assertTrue(queries <= 2,
+                "Typing eight letters cost " + queries + " queries: "
+                        + queryLog.countQueries() + " " + queryLog.pageQueries());
