+    }
+
+    /** Typing must not leave a trail of entries to press Back through. */
+    @Test
+    void filteringDoesNotGrowTheHistory() {
+        int before = historyLength();
+
+        nameFilter().pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(60));
+        assertThat(summary()).hasText("Showing 15 of 500");
+        statusFilter().selectItem("ACTIVE");
+        assertThat(summary()).hasText("Showing 5 of 500");
+
+        assertEquals(before, historyLength());
+    }
+
+    @Test
+    void sortingKeepsWorkingWhileFiltered() {
+        nameFilter().fill("vir");
+        assertThat(summary()).hasText("Showing 15 of 500");
+
+        grid().findHeaderCellByText("First name").orElseThrow().click();
+
+        assertThat(grid().getLocator().getByText("Beatriz").first()).isVisible();
+        assertEquals(15, grid().getTotalRowCount());
+    }
+
+    // --- helpers ---------------------------------------------------------
+
+    private Locator nameFilter() {
+        return page.locator("input[placeholder='Filter by name']");
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private Locator summary() {
+        return page.locator("#summary");
+    }
+
+    private GridElement grid() {
+        return GridElement.get(page);
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+}
